/usr/bin/bash -lc "python3 - <<'PY'
import zipfile, xml.etree.ElementTree as ET, re
from pathlib import Path
p=Path('outputs/technical-specification.docx')
assert p.exists() and p.stat().st_size>0
with zipfile.ZipFile(p) as z:
    bad=[]
    for name in z.namelist():
        if name.endswith('.xml') or name.endswith('.rels'):
            try: ET.fromstring(z.read(name))
            except Exception as e: bad.append((name,str(e)))
    assert not bad, bad
    root=ET.fromstring(z.read('word/document.xml'))
ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
text='\\n'.join(t.text or '' for t in root.findall('.//w:t',ns))
checks = {
 'sections': all(s in text for s in ['1 Наименование','2 Цель','3 Технические','4 Технико-экономические','5 Требования к видам','6 Требования к сырью','7 Требования к консервации','8 Специальные']),
 'normative': all(s in text for s in ['ГОСТ 15.016—2016','ITU-T G.703','RFC 4553 (SAToP)','RFC 5086 (CESoPSN)','PICMG AMC.0 R2.0','ГОСТ РВ 20.39.304-98','ГОСТ В 25803-91','ГОСТ 15150']),
 'parameters': all(s in text for s in ['8 экранированных RJ-48C','120 Ом','2048 кбит/с','±50 ppm','1500 В RMS','1–64 мс','73,5 × 180,6 × 28,95 мм','≤12 Вт','≤35 Вт','15 000 ч','20 лет']),
 'diagnostics': all(s in text for s in ['LOS','LOF','AIS','RAI','CRC-4','Frame slips','ES, SES, UAS','PRBS 2"'^15−1 и 2''^23−1'"']),
 'gaps_marked': '[уточнить]' in text,
 'tables': len(root.findall('.//w:tbl',ns)) >= 10,
}
print('xml files:', 'OK')
print('size:', p.stat().st_size)
print('tables:', len(root.findall('.//w:tbl',ns)))
for k,v in checks.items(): print(k, 'OK' if v else 'FAIL')
if not all(checks.values()): raise SystemExit(1)
PY
ls -l outputs/technical-specification.docx"

